process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
import fs from 'fs';
import { execSync } from 'child_process';
const B='https://dev.avesa.lt';
const U=process.env.WP_USER,P=(process.env.WP_APP_PASS||'').replace(/\s+/g,'');
const AUTH='Basic '+Buffer.from(U+':'+P).toString('base64');
const TOK=process.env.GH_TOKEN||'';
fs.mkdirSync('screenshots',{recursive:true});
const out={marker:'RINK DEPLOY RUN v1',ts:new Date().toISOString()};
async function wp(p,o={}){try{const r=await fetch(B+p,{...o,headers:{'Authorization':AUTH,'Content-Type':'application/json',...(o.headers||{})}});return{status:r.status,text:await r.text()}}catch(e){return{status:0,text:String(e)}}}
function js(t){const i=Math.min(...['[','{'].map(c=>{const x=t.indexOf(c);return x<0?1e9:x}));try{return JSON.parse(t.slice(i))}catch(e){return null}}

const php=Buffer.from('','base64').toString('utf8');
const sr=await wp('/wp-json/code-snippets/v1/snippets',{method:'POST',body:JSON.stringify({name:'TEMP Rink Deploy v1',code:php,scope:'global',active:true,priority:5})});
const sn=js(sr.text); out.snip=sn&&sn.id?sn.id:null; out.snip_status=sr.status;
await new Promise(r=>setTimeout(r,3000));

// failo turinys base64 (idetas kaip atskiras konstantas)
const FILE_B64='';
fs.writeFileSync('/tmp/payload.txt','turinys='+encodeURIComponent(FILE_B64));
const APPLY = process.env.RINK_APPLY==='1' ? '&apply=1' : '';
try{
  const res=execSync(`curl -sk -X POST "${B}/?ps_deploy=Dp77Kk3${APPLY}" --data @/tmp/payload.txt --max-time 120`,{encoding:'utf8',maxBuffer:20*1024*1024});
  out.deploy=js(res); if(!out.deploy) out.raw=res.slice(0,2000);
}catch(e){ out.err=String(e).slice(0,500); }

if(out.snip){const d=await wp('/wp-json/code-snippets/v1/snippets/'+out.snip,{method:'POST',body:JSON.stringify({active:false})});out.deact=d.status;}
const r=await fetch('https://api.github.com/repos/raimis079-creator/petshop-bridge/contents/screenshots/rink_deploy.json',{method:'PUT',headers:{'Authorization':'Bearer '+TOK,'Content-Type':'application/json','User-Agent':'b'},body:JSON.stringify({message:'rinkrec result deploy',content:Buffer.from(JSON.stringify(out,null,1)).toString('base64')})});
console.log('put',r.status);
